export type BarriosMap = Record<
  string, // provincia
  Record<
    string, // cantón
    Record<
      string, // distrito
      string[] // barrios/poblados
    >
  >
>

export interface Coordenadas {
  lat: number
  lng: number
}

export type CoordsMap = Record<
  string, // provincia
  Record<
    string, // cantón
    Record<
      string, // distrito
      Coordenadas
    >
  >
>

